@if ($logo || $slides)
<script id="lcc-theme-public-login-script">
(function () {
    const logo = @json($logo);
    const name = @json($options['brand_name'] ?: 'Company');
    const slides = @json($slides);
    function applyLoginTheme() {
        if (logo) {
            const original = document.querySelector('#app img[src*="akaunting-logo"]');
            if (original) {
                original.src = logo;
                original.alt = name;
                original.classList.add('lcc-theme-login-logo');
                original.style.cssText = 'height:3.5rem;width:auto;max-width:12rem;object-fit:contain;';
            }
        }
        if (!slides.length) return;
        const container = document.querySelector('#app .swiper-container');
        const wrapper = container?.querySelector('.swiper-wrapper');
        if (!container || !wrapper) return;

        // Build DOM exclusively through textContent and safe image URLs from
        // the application's own public filesystem, not untrusted HTML.
        const nodes = slides.map(function (slide) {
            const panel = document.createElement('div');
            panel.className = 'swiper-slide lcc-theme-carousel-slide flex justify-center flex-col items-center';
            const imageFrame = document.createElement('div');
            imageFrame.className = 'lcc-theme-carousel-media';
            imageFrame.style.cssText = 'width:min(420px,94%);height:285px;';
            const image = document.createElement('img');
            image.src = slide.image;
            image.alt = slide.title;
            image.style.cssText = 'max-width:100%;max-height:100%;object-fit:contain;';
            imageFrame.appendChild(image);
            panel.appendChild(imageFrame);
            const title = document.createElement('h1');
            title.className = 'lcc-theme-carousel-title';
            title.textContent = slide.title;
            panel.appendChild(title);
            if (slide.caption) {
                const caption = document.createElement('p');
                caption.className = 'lcc-theme-carousel-caption';
                caption.textContent = slide.caption;
                panel.appendChild(caption);
            }
            return panel;
        });

        if (container.swiper) {
            // Akaunting registers Navigation/Pagination/Autoplay, but NOT the
            // optional Swiper Manipulation plugin. removeAllSlides and
            // appendSlide are therefore undefined in the real Core bundle.
            // Rebuild the slide nodes without optional Swiper extensions.
            const swiper = container.swiper;
            swiper.autoplay?.stop?.();
            if (swiper.params?.loop && typeof swiper.loopDestroy === 'function') {
                swiper.loopDestroy();
            }
            wrapper.replaceChildren(...nodes);
            if (swiper.params?.loop && typeof swiper.loopCreate === 'function') {
                swiper.loopCreate();
            }
            swiper.update();
            if (typeof swiper.slideToLoop === 'function') {
                swiper.slideToLoop(0, 0);
            } else {
                swiper.slideTo(0, 0);
            }
            swiper.autoplay?.start?.();
        } else {
            wrapper.replaceChildren(...nodes);
        }
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', applyLoginTheme, {once: true});
    } else {
        applyLoginTheme();
    }
})();
</script>
@endif
